# --- Tests ---
Path('tests/combo-powerups.test.ts').write_text('''import { describe, expect, it } from 'vitest'\nimport { GameState, TARGET_ENEMIES } from '../src/game/sim/GameState'\n\nfunction prepKills(state: GameState, count: number): void {\n  for (const enemy of state.enemies.items) enemy.active = false\n  for (let i = 0; i < count; i += 1) {\n    const enemy = state.enemies.items[i]\n    enemy.active = true\n    enemy.hp = 1\n    enemy.mass = 1\n    enemy.radius = 10\n    enemy.x = 54 + (i % 3) * 8\n    enemy.y = (i - Math.floor(count / 2)) * 3\n    enemy.speed = 0\n    enemy.vx = 0\n    enemy.vy = 0\n    enemy.impulseX = 0\n    enemy.impulseY = 0\n    enemy.staggerTicks = 0\n  }\n}\n\ndescribe('combat reward loop v0', () => {\n  it('keeps the active horde intentionally below 60', () => {\n    expect(TARGET_ENEMIES).toBe(48)\n    expect(new GameState(1).enemies.activeCount()).toBe(48)\n  })\n\n  it('builds a multiplier and attack-speed reward from consecutive kills', () => {\n    const state = new GameState(2)\n    prepKills(state, 4)\n    state.step({ x: 0, y: 0, aimRadians: 0, slash: true })\n    expect(state.kills).toBeGreaterThanOrEqual(4)\n    expect(state.comboMultiplier()).toBeGreaterThanOrEqual(2)\n    expect(state.attackSpeedMultiplier()).toBeGreaterThan(1)\n    expect(state.score).toBeGreaterThanOrEqual(800)\n  })\n\n  it('freezes the world at an 8-kill chain milestone while preserving deterministic ticks', () => {\n    const state = new GameState(3)\n    prepKills(state, 8)\n    state.step({ x: 0, y: 0, aimRadians: 0, whirlwind: true })\n    expect(state.comboKills).toBeGreaterThanOrEqual(8)\n    expect(state.freezeTicksRemaining()).toBeGreaterThan(0)\n    expect(state.events.some((event) => event.type === 'flow-freeze' && event.source === 'combo')).toBe(true)\n  })\n\n  it('guarantees a deterministic powerup drop every sixth kill', () => {\n    const state = new GameState(4)\n    prepKills(state, 6)\n    state.step({ x: 0, y: 0, aimRadians: 0, whirlwind: true })\n    expect(state.powerups.some((powerup) => powerup.active)).toBe(true)\n    expect(state.events.some((event) => event.type === 'powerup-drop')).toBe(true)\n  })\n})\n''')

# --- Design receipt ---
Path('docs/COMBAT_REWARD_V0.md').write_text('''# Combat Reward V0\n\n## Intent\nReward aggressive, readable cutting rather than restoring horde spam. Active population is frozen at 48.\n\n## Chain / multiplier\n- Kill window: 150 fixed ticks (~2.5s).\n- 0–3 chain: ×1 score.\n- 4–7: ×2 score + 1.12× cut speed.\n- 8–11: ×3 score + 1.25× cut speed.\n- 12+: ×4 score + 1.35× cut speed.\n- Every 8 consecutive kills triggers a 36-tick world freeze. Player input/attacks continue while enemies stop advancing.\n\n## Powerups\nEvery sixth kill deterministically drops one powerup, with type selected from the run RNG:\n- `frenzy`: 6 seconds, additional 1.45× attack-speed multiplier.\n- `freeze`: 90-tick time freeze.\n- `apple-juice`: heal 1 HP up to max.\n\nDrops are authoritative simulation state with pickup radius and TTL. Presentation cannot invent pickups or effects.\n\n## Apple Inu head silhouette\nThe head is silhouette-first: two top lobes, a hard top cleft, tapered bottom, oversized three-step side bite, stem and leaf. Jaw/sword layers remain inside that silhouette so the head should read as a bitten apple before it reads as a dog face. The side-bite sword pose is preserved.\n''')
